# Configuration file for the Sphinx documentation builder.
#
# The setup follows the one generated by `ontokit docs` in EMMOntoPy (used for
# the SSbD Core ontology documentation), without the ontology reference index.
# _static/custom.css and _static/toc-collapsible.js are copied from
# EMMOntoPy (ontopy/ontokit/setuptemplates).
#
# Build with: sphinx-build -b html docs public

import time

# -- Project information -----------------------------------------------------

project = "PINK Annotation Schema"
author = "PINK project"
copyright = f"{time.strftime('%Y')}, {author}"

# -- General configuration ---------------------------------------------------

extensions = [
    "myst_parser",
    "sphinx_design",
]

source_suffix = {
    ".rst": "restructuredtext",
    ".md": "markdown",
}

exclude_patterns = ["_build", "Thumbs.db", ".DS_Store", "requirements.txt"]

# Make anchors for headings, so that pages can link to sections (page.md#section)
myst_heading_anchors = 3

pygments_style = "friendly"
pygments_dark_style = "lightbulb"

# -- Options for HTML output -------------------------------------------------

html_theme = "pydata_sphinx_theme"

html_theme_options = {
    "show_nav_level": 2,
    "show_toc_level": 0,
    "secondary_sidebar_items": [],
    "navbar_center": ["navbar-nav"],
    "navbar_end": ["navbar-icon-links", "theme-switcher", "search-button"],
    "icon_links": [
        {
            "name": "GitHub",
            "url": "https://github.com/PINK-project/PINK-annotation-schema",
            "icon": "fa-brands fa-github",
        },
        {
            "name": "SSbD Core Ontology",
            "url": "https://ssbd-ontology.github.io/core/",
            "icon": "fa-solid fa-globe",
        },
    ],
    "show_prev_next": False,
    "footer_start": ["copyright"],
    "footer_center": ["sphinx-version"],
}

# For the "Edit on GitHub" link
html_context = {
    "github_user": "PINK-project",
    "github_repo": "PINK-annotation-schema",
    "github_version": "main",
    "doc_path": "docs",
}

html_static_path = ["_static"]
html_title = "PINK Annotation Schema"
html_css_files = ["custom.css"]
html_js_files = ["toc-collapsible.js"]

html_sidebars = {
    "**": ["search-field.html", "page-toc.html", "edit-this-page.html"],
}
